import subprocess, json, collections
def run(tree, extra=[]):
    data={"schema-version":"2024-11-02","pdu":"0.21.1","unit":"bytes","tree":tree}
    p=subprocess.run(["/workspace/executable","--json-input","--min-ratio=0","-w","120"]+extra, input=json.dumps(data), capture_output=True, text=True)
    print(p.stdout)
    for line in p.stdout.splitlines():
        idx=[i for i,ch in enumerate(line) if ch=="│"]
        if len(idx)>=2:
            bar=line[idx[-2]+1:idx[-1]]
            # run-length encode
            rle=[]
            for ch in bar:
                if rle and rle[-1][0]==ch: rle[-1][1]+=1
                else: rle.append([ch,1])
            print(rle, line[:idx[-2]])
    print("===")

# chain decreasing
def chain(names,sizes):
    if not names: return None
    node={"name":names[0],"size":sizes[0],"children":[]}
    if len(names)>1:
        node["children"]=[chain(names[1:],sizes[1:])]
    return node

run(chain(["root","a","b","c","d","e","f","g"],[1000,900,800,700,600,500,400,300]))
# also sibling tree deeper
