def makepty(cols):
    m,s=pty.openpty(); fcntl.ioctl(s, termios.TIOCSWINSZ, struct.pack("HHHH",24,cols,0,0)); return m,s

def test(out_cols, err_cols, in_cols):
    masters=[]; slaves={}
    kwargs={}
    # use PIPE for stdout capture if out_cols is None else pty
    fds={}
    for name,cols in [("stdout",out_cols),("stderr",err_cols),("stdin",in_cols)]:
        if cols is None:
            kwargs[name]=subprocess.PIPE if name!="stdin" else subprocess.DEVNULL
        else:
