use clap::builder::{PossibleValue, ValueParser};
use clap::{Arg, ArgAction, ColorChoice, Command};
use rayon::prelude::*;
use serde::{Deserialize, Deserializer, Serialize};
use std::collections::{BTreeMap, HashMap, HashSet};
use std::ffi::OsString;
use std::fmt::{self, Display};
use std::fs;
use std::io::{self, Write};
use std::num::NonZeroUsize;
use std::os::unix::ffi::OsStrExt;
use std::os::unix::fs::MetadataExt;
use std::path::{Path, PathBuf};
use std::process::ExitCode;
use std::str::FromStr;
use std::sync::atomic::{AtomicU64, Ordering};
use std::sync::{mpsc, Arc, Mutex};
use std::thread::{self, JoinHandle};
use std::time::Duration;
use unicode_width::UnicodeWidthStr;

// ---------- CLI value types ----------

#[derive(Clone, Debug, PartialEq, Eq)]
enum BytesFormat {
    Plain,
    Metric,
    Binary,
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum Quantity {
    ApparentSize,
    BlockSize,
    BlockCount,
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum MaxDepth {
    Infinite,
    Finite(NonZeroUsize),
}

impl FromStr for MaxDepth {
    type Err = String;
    fn from_str(input: &str) -> Result<Self, Self::Err> {
        let text = input.trim();
        if text == "inf" {
            return Ok(Self::Infinite);
        }
        text.parse::<NonZeroUsize>()
            .map(Self::Finite)
            .map_err(|error| {
                format!(
                    "Value is neither \"inf\" nor a positive integer: {error}"
                )
            })
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
enum Threads {
    Auto,
    Max,
    Number(NonZeroUsize),
}

impl FromStr for Threads {
    type Err = String;
    fn from_str(input: &str) -> Result<Self, Self::Err> {
        let text = input.trim();
        match text {
            "auto" => return Ok(Self::Auto),
            "max" => return Ok(Self::Max),
            _ => {}
        }
        text.parse::<NonZeroUsize>()
            .map(Self::Number)
            .map_err(|error| {
                format!(
                    "Value is neither \"auto\", \"max\", nor a number: {error}"
                )
            })
    }
}

fn parse_min_ratio(input: &str) -> Result<f64, String> {
    let value = input.parse::<f64>().map_err(|error| error.to_string())?;
    if value < 0.0 {
        return Err("less than 0".to_string());
    }
    if value >= 1.0 {
        return Err("greater than or equal to 1".to_string());
    }
    Ok(value)
}

struct Args {
    files: Vec<PathBuf>,
    json_input: bool,
    json_output: bool,
    bytes_format: BytesFormat,
    deduplicate_hardlinks: bool,
    top_down: bool,
    align_right: bool,
    quantity: Quantity,
    max_depth: MaxDepth,
    total_width: Option<usize>,
    column_width: Option<(usize, usize)>,
    min_ratio: f64,
    no_sort: bool,
    silent_errors: bool,
    progress: bool,
    threads: Threads,
    omit_json_shared_details: bool,
    omit_json_shared_summary: bool,
}

fn build_command() -> Command {
    Command::new("pdu")
        .version(env!("CARGO_PKG_VERSION"))
        .color(ColorChoice::Never)
        .about("Summarize disk usage of the set of files, recursively for directories.")
