                .long_help("Maximum depth to display the data. Could be either \"inf\" or a positive integer")
                .value_name("MAX_DEPTH")
                .visible_alias("depth")
                .value_parser(ValueParser::new(|s: &str| s.parse::<MaxDepth>()))
                .default_value("10"),
        )
        .arg(
            Arg::new("total-width")
                .short('w')
                .long("total-width")
                .help("Width of the visualization")
                .value_name("TOTAL_WIDTH")
                .visible_alias("width")
                .value_parser(clap::value_parser!(usize))
                .conflicts_with("column-width"),
        )
        .arg(
            Arg::new("column-width")
                .long("column-width")
                .help("Maximum widths of the tree column and width of the bar column")
                .value_names(["TREE_WIDTH", "BAR_WIDTH"])
                .num_args(2)
                .value_parser(clap::value_parser!(usize)),
        )
        .arg(
            Arg::new("min-ratio")
                .short('m')
                .long("min-ratio")
                .help("Minimal size proportion required to appear")
                .value_name("MIN_RATIO")
                .value_parser(ValueParser::new(parse_min_ratio))
                .default_value("0.01"),
        )
        .arg(
            Arg::new("no-sort")
                .long("no-sort")
                .help("Do not sort the branches in the tree")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("silent-errors")
                .short('s')
                .long("silent-errors")
                .help("Prevent filesystem error messages from appearing in stderr")
                .long_help("Prevent filesystem error messages from appearing in stderr")
                .visible_alias("no-errors")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("progress")
                .short('p')
                .long("progress")
                .help("Report progress being made at the expense of performance")
                .action(ArgAction::SetTrue),
        )
        .arg(
            Arg::new("threads")
                .long("threads")
                .help("Set the maximum number of threads to spawn. Could be either \"auto\", \"max\", or a positive integer")
                .long_help("Set the maximum number of threads to spawn. Could be either \"auto\", \"max\", or a positive integer")
                .value_name("THREADS")
                .value_parser(ValueParser::new(|s: &str| s.parse::<Threads>()))
                .default_value("auto"),
        )
        .arg(
            Arg::new("omit-json-shared-details")
                .long("omit-json-shared-details")
                .help("Do not output `.shared.details` in the JSON output")
                .action(ArgAction::SetTrue)
                .requires_all(["json-output", "deduplicate-hardlinks"]),
        )
        .arg(
            Arg::new("omit-json-shared-summary")
                .long("omit-json-shared-summary")
                .help("Do not output `.shared.summary` in the JSON output")
                .action(ArgAction::SetTrue)
                .requires_all(["json-output", "deduplicate-hardlinks"]),
        )
}

fn parse_args() -> Args {
    let matches = build_command().get_matches();
    let bytes_format = match matches
        .get_one::<String>("bytes-format")
        .expect("default")
        .as_str()
    {
        "plain" => BytesFormat::Plain,
        "binary" => BytesFormat::Binary,
        _ => BytesFormat::Metric,
    };
    let quantity = match matches
        .get_one::<String>("quantity")
        .expect("default")
        .as_str()
    {
        "apparent-size" => Quantity::ApparentSize,
        "block-count" => Quantity::BlockCount,
        _ => Quantity::BlockSize,
    };
    let column_width = matches.get_many::<usize>("column-width").map(|mut values| {
        let tree = *values.next().expect("two values");
        let bar = *values.next().expect("two values");
        (tree, bar)
    });
    Args {
        files: matches
            .get_many::<PathBuf>("files")
            .map(|values| values.cloned().collect())
            .unwrap_or_default(),
        json_input: matches.get_flag("json-input"),
        json_output: matches.get_flag("json-output"),
        bytes_format,
        deduplicate_hardlinks: matches.get_flag("deduplicate-hardlinks"),
        top_down: matches.get_flag("top-down"),
        align_right: matches.get_flag("align-right"),
        quantity,
        max_depth: matches
            .get_one::<MaxDepth>("max-depth")
            .expect("default")
            .clone(),
        total_width: matches.get_one::<usize>("total-width").copied(),
        column_width,
        min_ratio: *matches.get_one::<f64>("min-ratio").expect("default"),
        no_sort: matches.get_flag("no-sort"),
        silent_errors: matches.get_flag("silent-errors"),
        progress: matches.get_flag("progress"),
        threads: matches.get_one::<Threads>("threads").expect("default").clone(),
        omit_json_shared_details: matches.get_flag("omit-json-shared-details"),
        omit_json_shared_summary: matches.get_flag("omit-json-shared-summary"),
    }
}

