impl FromStr for MaxDepth {
    type Err = String;
    fn from_str(input: &str) -> Result<Self, Self::Err> {
        let text = input.trim();
        if text == "inf" {
            return Ok(Self::Infinite);
        }
        text.parse::<NonZeroUsize>()
            .map(Self::Finite)
            .map_err(|error| {
