#[derive(Clone, Debug)]
struct OsStringDisplay(OsString);

impl Display for OsStringDisplay {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self.0.to_str() {
            Some(text) => formatter.write_str(text),
            None => write!(formatter, "{:?}", self.0),
        }
    }
}

impl OsStringDisplay {
    fn into_string(self) -> Result<String, Self> {
        match self.0.into_string() {
            Ok(text) => Ok(text),
            Err(raw) => Err(Self(raw)),
        }
    }
    fn as_os_str(&self) -> &std::ffi::OsStr {
        self.0.as_os_str()
    }
}

#[derive(Clone, Debug)]
struct DataTree<Name> {
    name: Name,
    size: u64,
    children: Vec<DataTree<Name>>,
}

impl<Name> DataTree<Name> {
    fn new(name: Name, size: u64, children: Vec<DataTree<Name>>) -> Self {
