// ---------- Size, unit, formatting ----------

#[derive(Clone, Copy, Debug, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "lowercase")]
enum Unit {
    Bytes,
    Blocks,
}

#[derive(Clone, Copy, Debug, PartialEq, Eq)]
enum Sized {
    Bytes(u64),
    Blocks(u64),
}

impl Sized {
    fn value(self) -> u64 {
        match self {
            Self::Bytes(value) | Self::Blocks(value) => value,
        }
    }
}

fn format_bytes(size: u64, format: &BytesFormat) -> String {
    match format {
        BytesFormat::Plain => size.to_string(),
        BytesFormat::Metric => format_scaled(size, 1000),
        BytesFormat::Binary => format_scaled(size, 1024),
    }
}

fn format_scaled(size: u64, base: u64) -> String {
    if size < base {
        return format!("{size}   ");
    }
    let exponent = size.ilog(base).min(5);
    let unit = ['K', 'M', 'G', 'T', 'P'][(exponent - 1) as usize];
    let scaled = size as f32 / base.pow(exponent) as f32;
    format!("{scaled:.1}{unit}")
}

fn format_sized(size: Sized, format: &BytesFormat) -> String {
    match size {
        Sized::Blocks(value) => value.to_string(),
        Sized::Bytes(value) => format_bytes(value, format),
    }
}

fn unit_of(quantity: &Quantity) -> Unit {
    match quantity {
        Quantity::BlockCount => Unit::Blocks,
        _ => Unit::Bytes,
    }
}

fn sized_from_unit(value: u64, unit: Unit) -> Sized {
    match unit {
        Unit::Bytes => Sized::Bytes(value),
        Unit::Blocks => Sized::Blocks(value),
    }
}

// ---------- JSON structures ----------

const SCHEMA_VERSION: &str = "2024-11-02";

fn deserialize_schema<'de, D>(deserializer: D) -> Result<String, D::Error>
where
    D: Deserializer<'de>,
{
    let value = String::deserialize(deserializer)?;
    if value == SCHEMA_VERSION {
        Ok(value)
    } else {
        Err(serde::de::Error::custom(format!(
            "InvalidSchema: {value:?}: input schema is not {SCHEMA_VERSION:?}"
        )))
    }
}

#[derive(Serialize, Deserialize)]
struct JsonData {
    #[serde(rename = "schema-version", deserialize_with = "deserialize_schema")]
    schema_version: String,
    #[serde(skip_serializing_if = "Option::is_none")]
    pdu: Option<String>,
    unit: Unit,
    tree: Reflection,
    #[serde(skip_serializing_if = "Option::is_none")]
    shared: Option<JsonShared>,
}

#[derive(Clone, Serialize, Deserialize)]
struct Reflection {
    name: String,
    size: u64,
    children: Vec<Reflection>,
}

#[derive(Serialize, Deserialize)]
struct JsonShared {
    #[serde(skip_serializing_if = "Option::is_none")]
    details: Option<Vec<ReflectionEntry>>,
    #[serde(skip_serializing_if = "Option::is_none")]
    summary: Option<Summary>,
}

#[derive(Clone, Serialize, Deserialize)]
struct ReflectionEntry {
    ino: u64,
    size: u64,
    links: u64,
    paths: HashSet<PathBuf>,
}

#[derive(Clone, Copy, Serialize, Deserialize, Default)]
struct Summary {
    inodes: usize,
    exclusive_inodes: usize,
    all_links: usize,
    detected_links: usize,
    exclusive_links: usize,
    shared_size: u64,
    exclusive_shared_size: u64,
}

fn reflection_to_tree(node: Reflection) -> DataTree<String> {
    DataTree::new(
        node.name,
        node.size,
        node.children
            .into_iter()
            .map(reflection_to_tree)
            .collect(),
    )
}

fn tree_to_reflection(node: DataTree<OsStringDisplay>) -> Reflection {
    let children = node
        .children
        .into_iter()
        .map(tree_to_reflection)
        .collect();
    let name = node
        .name
        .into_string()
        .expect("convert all names from raw string to UTF-8");
    Reflection {
        name,
        size: node.size,
        children,
    }
}

// ---------- Application errors ----------

enum AppError {
    DeserializationFailure(serde_json::Error),
    JsonInputArgConflict,
    InvalidInputReflection {
        parent: PathBuf,
        parent_size: Sized,
        child_name: String,
        child_size: Sized,
    },
}

impl AppError {
    fn code(&self) -> u8 {
        match self {
            Self::DeserializationFailure(_) => 3,
            Self::JsonInputArgConflict => 4,
            Self::InvalidInputReflection { .. } => 5,
        }
    }
}

impl Display for AppError {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self {
            Self::DeserializationFailure(error) => {
                write!(formatter, "DeserializationFailure: {error}")
            }
            Self::JsonInputArgConflict => formatter.write_str(
                "JsonInputArgConflict: Arguments exist alongside --json-input",
            ),
            Self::InvalidInputReflection {
                parent,
                parent_size,
                child_name,
                child_size,
            } => write!(
                formatter,
                "InvalidInputReflection: ExcessiveChildren: {parent:?} ({parent_size:?}) is less than a child named {child_name:?} ({child_size:?})"
            ),
        }
    }
}

fn validate_json_tree(node: &DataTree<String>, unit: Unit) -> Result<(), AppError> {
    fn check(
        node: &DataTree<String>,
        unit: Unit,
        path: PathBuf,
    ) -> Result<(), AppError> {
        for child in &node.children {
            if child.size > node.size {
                return Err(AppError::InvalidInputReflection {
                    parent: path,
                    parent_size: sized_from_unit(node.size, unit),
                    child_name: child.name.clone(),
                    child_size: sized_from_unit(child.size, unit),
                });
            }
        }
        for child in &node.children {
            let mut child_path = path.clone();
            child_path.push(&child.name);
            check(child, unit, child_path)?;
        }
        Ok(())
    }
    check(node, unit, PathBuf::from(&node.name))
}

// ---------- Hardlinks ----------

#[derive(Clone)]
struct HardlinkRecord {
    size: u64,
    links: u64,
    paths: HashSet<PathBuf>,
    path_counts: HashMap<PathBuf, usize>,
    detected_links: usize,
}

type HardlinkMap = BTreeMap<u64, HardlinkRecord>;

#[derive(Clone, Default)]
struct HardlinkCollector {
    records: Arc<Mutex<HardlinkMap>>,
}

impl HardlinkCollector {
    fn record(&self, ino: u64, size: u64, links: u64, path: PathBuf) {
        let mut records = self.records.lock().expect("hardlink mutex");
        let record = records.entry(ino).or_insert_with(|| HardlinkRecord {
            size,
            links,
            paths: HashSet::new(),
            path_counts: HashMap::new(),
            detected_links: 0,
        });
        record.paths.insert(path.clone());
        *record.path_counts.entry(path).or_insert(0) += 1;
        record.detected_links += 1;
    }

    fn snapshot(&self) -> HardlinkMap {
        self.records.lock().expect("hardlink mutex").clone()
    }
}

fn summarize_records<'a, I>(records: I) -> Summary
where
    I: Iterator<Item = (u64, usize, u64)>, // links, detected, size
{
    let mut summary = Summary::default();
    for (links, detected, size) in records {
        if (detected as u64) > links {
            panic!(
                "Impossible! Total of nlink ({links}) is less than detected paths ({detected}). Something must have gone wrong!"
            );
        }
        summary.inodes += 1;
        summary.all_links += links as usize;
        summary.detected_links += detected;
        summary.shared_size = summary.shared_size.wrapping_add(size);
        if detected as u64 == links {
            summary.exclusive_inodes += 1;
            summary.exclusive_links += detected;
            summary.exclusive_shared_size =
                summary.exclusive_shared_size.wrapping_add(size);
        }
    }
    summary
}

fn summary_of_map(records: &HardlinkMap) -> Summary {
    summarize_records(
        records
            .values()
            .map(|record| (record.links, record.detected_links, record.size)),
    )
}

fn summary_of_details(details: &[ReflectionEntry]) -> Summary {
    summarize_records(
        details
            .iter()
            .map(|entry| (entry.links, entry.paths.len(), entry.size)),
    )
}

fn render_summary(summary: &Summary, unit: Unit, format: &BytesFormat) -> String {
    if summary.inodes == 0 {
        return "There are no hardlinks.".to_string();
    }
    let shared = format_sized(sized_from_unit(summary.shared_size, unit), format);
    if summary.exclusive_inodes == 0 {
        return format!(
            "Hardlinks detected! All hardlinks within this tree have links without\n* Number of shared inodes: {}\n* Total number of links: {} total, {} detected\n* Total shared size: {}",
            summary.inodes, summary.all_links, summary.detected_links, shared
        );
    }
    if summary.exclusive_inodes == summary.inodes {
        return format!(
            "Hardlinks detected! No files have links outside this tree\n* Number of shared inodes: {}\n* Total number of links: {}\n* Total shared size: {}",
            summary.inodes, summary.all_links, shared
        );
    }
    let exclusive_shared = format_sized(
        sized_from_unit(summary.exclusive_shared_size, unit),
        format,
    );
    format!(
        "Hardlinks detected! Some files have links outside this tree\n* Number of shared inodes: {} total, {} exclusive\n* Total number of links: {} total, {} detected, {} exclusive\n* Total shared size: {} total, {} exclusive",
        summary.inodes,
        summary.exclusive_inodes,
        summary.all_links,
        summary.detected_links,
        summary.exclusive_links,
        shared,
        exclusive_shared
    )
}

// ---------- Reporter ----------

struct ReporterState {
    progress_len: usize,
}

struct Reporter {
    silent_errors: bool,
    progress_enabled: bool,
    scanned_count: AtomicU64,
    scanned_total: AtomicU64,
    state: Mutex<ReporterState>,
    stop_sender: Mutex<Option<mpsc::Sender<()>>>,
    progress_thread: Mutex<Option<JoinHandle<()>>>,
}

impl Reporter {
    fn new(silent_errors: bool, progress_enabled: bool) -> Arc<Self> {
        let reporter = Arc::new(Self {
            silent_errors,
            progress_enabled,
            scanned_count: AtomicU64::new(0),
            scanned_total: AtomicU64::new(0),
            state: Mutex::new(ReporterState { progress_len: 0 }),
            stop_sender: Mutex::new(None),
            progress_thread: Mutex::new(None),
        });
        if progress_enabled {
            let (sender, receiver) = mpsc::channel::<()>();
            let weak = Arc::downgrade(&reporter);
            let handle = thread::spawn(move || loop {
                match receiver.recv_timeout(Duration::from_millis(100)) {
                    Ok(()) | Err(mpsc::RecvTimeoutError::Disconnected) => break,
                    Err(mpsc::RecvTimeoutError::Timeout) => {
                        let Some(reporter) = weak.upgrade() else { break };
                        reporter.show_progress();
                    }
                }
            });
            *reporter.stop_sender.lock().expect("reporter mutex") = Some(sender);
            *reporter.progress_thread.lock().expect("reporter mutex") = Some(handle);
        }
        reporter
    }

    fn show_progress(&self) {
        let count = self.scanned_count.load(Ordering::Relaxed);
        let total = self.scanned_total.load(Ordering::Relaxed);
        let text = format!("(scanned {count}, total {total})");
        let mut state = self.state.lock().expect("reporter mutex");
        let mut stderr = io::stderr().lock();
        let _ = write!(stderr, "\r{}\r\r{}", " ".repeat(state.progress_len), text);
        let _ = stderr.flush();
        state.progress_len = text.len();
    }

    fn report_progress(&self, size: u64) {
        if self.progress_enabled {
            self.scanned_count.fetch_add(1, Ordering::Relaxed);
            self.scanned_total.fetch_add(size, Ordering::Relaxed);
        }
    }

    fn report_error(&self, operation: &str, path: &Path, error: &io::Error) {
        if self.silent_errors {
            return;
        }
        let mut state = self.state.lock().expect("reporter mutex");
        let mut stderr = io::stderr().lock();
        let _ = write!(
            stderr,
            "\r{}\r[error] {operation} {path:?}: {error}\n",
            " ".repeat(state.progress_len)
        );
        let _ = stderr.flush();
        state.progress_len = 0;
    }

    fn finish(&self) {
        if let Some(sender) = self.stop_sender.lock().expect("reporter mutex").take() {
            let _ = sender.send(());
        }
        if let Some(handle) = self.progress_thread.lock().expect("reporter mutex").take() {
            let _ = handle.join();
        }
        let mut state = self.state.lock().expect("reporter mutex");
        let mut stderr = io::stderr().lock();
        let _ = write!(stderr, "\r{}\r", " ".repeat(state.progress_len));
        let _ = stderr.flush();
        state.progress_len = 0;
    }
}

// ---------- Filesystem traversal ----------

struct TreeBuilder {
    quantity: Quantity,
    sort: bool,
    reporter: Arc<Reporter>,
    hardlinks: Option<HardlinkCollector>,
}

impl TreeBuilder {
    fn own_size(&self, metadata: &fs::Metadata) -> u64 {
        match self.quantity {
            Quantity::ApparentSize => metadata.len(),
            Quantity::BlockSize => metadata.blocks().wrapping_mul(512),
            Quantity::BlockCount => metadata.blocks(),
        }
    }

    fn build(&self, path: PathBuf, name: OsStringDisplay) -> DataTree<OsStringDisplay> {
        let metadata = match fs::symlink_metadata(&path) {
            Ok(metadata) => metadata,
            Err(error) => {
                self.reporter.report_error("symlink_metadata", &path, &error);
                return DataTree::new(name, 0, Vec::new());
            }
        };
        let own_size = self.own_size(&metadata);
        self.reporter.report_progress(own_size);

        if !metadata.is_dir() {
            if let Some(collector) = &self.hardlinks {
                let links = metadata.nlink();
                if links > 1 {
                    collector.record(metadata.ino(), own_size, links, path.clone());
                }
            }
            return DataTree::new(name, own_size, Vec::new());
        }

        let read_dir = match fs::read_dir(&path) {
            Ok(read_dir) => read_dir,
            Err(error) => {
                self.reporter.report_error("read_dir", &path, &error);
                return DataTree::new(name, 0, Vec::new());
            }
        };
        let mut entries = Vec::new();
        for entry in read_dir {
            match entry {
                Ok(entry) => entries.push(entry),
                Err(error) => self.reporter.report_error("read_dir", &path, &error),
            }
        }
        let mut children: Vec<DataTree<OsStringDisplay>> = entries
            .into_par_iter()
            .map(|entry| {
                let child_path = entry.path();
                let child_name = OsStringDisplay(entry.file_name());
                self.build(child_path, child_name)
            })
            .collect();
        if self.sort {
            children.sort_by(|left, right| right.size.cmp(&left.size));
        }
        let size = children
            .iter()
            .fold(own_size, |total, child| total.wrapping_add(child.size));
        DataTree::new(name, size, children)
    }
}

fn remove_overlapping_dir_args(files: Vec<PathBuf>) -> Vec<PathBuf> {
    let canonical_dirs: Vec<Option<PathBuf>> = files
        .iter()
        .map(|path| {
            let metadata = fs::symlink_metadata(path).ok()?;
            if !metadata.is_dir() {
                return None;
            }
            fs::canonicalize(path).ok()
        })
        .collect();
    let mut retained = Vec::new();
    for (index, path) in files.into_iter().enumerate() {
        if let Some(canonical) = &canonical_dirs[index] {
            let overlaps = canonical_dirs
                .iter()
                .enumerate()
                .any(|(other_index, other)| {
                    let Some(other) = other else { return false };
                    if other_index == index {
                        return false;
                    }
                    if canonical == other {
                        other_index < index
                    } else {
                        canonical.starts_with(other)
                    }
                });
            if overlaps {
                continue;
            }
        }
        retained.push(path);
    }
    retained
}

fn prune_tree<Name>(
    tree: &mut DataTree<Name>,
    max_depth: &MaxDepth,
    min_ratio: f64,
) {
    let threshold = tree.size as f64 * min_ratio;
    fn apply<Name>(
        node: &mut DataTree<Name>,
        depth: usize,
        max_depth: &MaxDepth,
        threshold: f64,
    ) {
        if let MaxDepth::Finite(limit) = max_depth {
            if depth >= limit.get() {
                node.children.clear();
                return;
            }
        }
        node.children
            .retain(|child| !(child.size as f64) .lt(&threshold));
        for child in &mut node.children {
            apply(child, depth + 1, max_depth, threshold);
        }
    }
    apply(tree, 1, max_depth, threshold);
}

fn adjust_hardlinked_sizes(
    tree: &mut DataTree<OsStringDisplay>,
    records: &HardlinkMap,
    root_is_total: bool,
) {
    fn visit(
        node: &mut DataTree<OsStringDisplay>,
        records: &HardlinkMap,
        current_path: Option<PathBuf>,
    ) {
        for record in records.values() {
            let count: usize = match &current_path {
                None => record.detected_links,
                Some(prefix) => record
                    .path_counts
                    .iter()
                    .filter(|(path, _)| path.starts_with(prefix))
                    .map(|(_, count)| *count)
                    .sum(),
            };
            if count > 1 {
                let deduction = ((count - 1) as u64).wrapping_mul(record.size);
                node.size = node.size.wrapping_sub(deduction);
            }
        }
        for child in &mut node.children {
            let child_path = match &current_path {
                None => Some(PathBuf::from(child.name.as_os_str())),
                Some(parent) => {
                    let mut path = parent.clone();
                    path.push(child.name.as_os_str());
                    Some(path)
                }
            };
            visit(child, records, child_path);
        }
    }

    let root_path = if root_is_total {
        None
    } else {
        Some(PathBuf::from(tree.name.as_os_str()))
    };
    visit(tree, records, root_path);
}

// ---------- Visualizer ----------

#[derive(Clone, Copy, PartialEq, Eq)]
enum Orientation {
    BottomUp,
    TopDown,
}

struct VisualNode<Name> {
    name: String,
    size: u64,
    children: Vec<VisualNode<Name>>,
    marker: std::marker::PhantomData<Name>,
}

fn build_visual_tree<Name: Display>(
    node: &DataTree<Name>,
    depth: usize,
    tree_width_max: usize,
) -> Option<VisualNode<Name>> {
    let prefix_width = depth.wrapping_mul(2).wrapping_add(3);
    if prefix_width > tree_width_max {
        return None;
    }
    let remaining = tree_width_max - prefix_width;
    let mut name = node.name.to_string();
    if UnicodeWidthStr::width(name.as_str()) > remaining {
        if remaining < 4 {
            return None;
        }
        name.truncate(remaining - 3);
        name.push_str("...");
    }
    let children = node
        .children
        .iter()
        .filter_map(|child| build_visual_tree(child, depth + 1, tree_width_max))
        .collect();
    Some(VisualNode {
        name,
        size: node.size,
        children,
        marker: std::marker::PhantomData,
    })
}

fn scaled_round(size: u64, total: u64, scale: u64) -> u64 {
    if total == 0 {
        return 0;
    }
    let product = size.wrapping_mul(scale);
    ((product as u128 + (total / 2) as u128) / total as u128) as u64
}

fn ancestor_char(depth: usize) -> char {
    match depth {
        0 => ' ',
        1 => '░',
        2 => '▒',
        _ => '▓',
    }
}

struct RowInfo {
    size_text: String,
    tree_text: String,
    ancestors: Vec<(u64, usize)>, // root..=self (size, depth)
    size: u64,
}

fn collect_rows<Name>(
    node: &VisualNode<Name>,
    depth: usize,
    is_last: bool,
    ancestors_last: &mut Vec<bool>,
    ancestors: &mut Vec<(u64, usize)>,
    orientation: Orientation,
    unit: Unit,
    bytes_format: &BytesFormat,
    rows: &mut Vec<RowInfo>,
) {
    let mut tree_text = String::new();
    for ancestor_index in 0..depth {
        if ancestors_last[ancestor_index] {
            tree_text.push_str("  ");
        } else {
            tree_text.push_str("│ ");
        }
    }
    let first = match orientation {
        Orientation::TopDown => {
            if is_last {
                '└'
            } else {
                '├'
            }
        }
        Orientation::BottomUp => {
            if is_last {
                '┌'
            } else {
                '├'
            }
        }
    };
    let third = if node.children.is_empty() {
        '─'
    } else {
        match orientation {
            Orientation::TopDown => '┬',
            Orientation::BottomUp => '┴',
        }
    };
    tree_text.push(first);
    tree_text.push('─');
    tree_text.push(third);
    tree_text.push_str(&node.name);

    ancestors.push((node.size, depth));
    rows.push(RowInfo {
        size_text: format_sized(sized_from_unit(node.size, unit), bytes_format),
        tree_text,
        ancestors: ancestors.clone(),
        size: node.size,
    });

    // ancestors_last[depth] stores this node's sibling status for descendants.
    if ancestors_last.len() == depth {
        ancestors_last.push(is_last);
    } else if ancestors_last.len() > depth {
        ancestors_last[depth] = is_last;
        ancestors_last.truncate(depth + 1);
    } else {
        while ancestors_last.len() < depth {
            ancestors_last.push(true);
        }
        ancestors_last.push(is_last);
    }

    let last_index = node.children.len().saturating_sub(1);
    for (index, child) in node.children.iter().enumerate() {
        collect_rows(
            child,
            depth + 1,
            index == last_index,
            ancestors_last,
            ancestors,
            orientation,
            unit,
            bytes_format,
            rows,
        );
    }
    ancestors.pop();
}

fn make_bar(
    ancestors: &[(u64, usize)],
    total: u64,
    bar_width: usize,
    align_right: bool,
) -> String {
    let width = bar_width.max(1);
    let mut segments: Vec<(char, u64)> = Vec::new(); // char, cumulative-boundary
    // Self is the last ancestor in the list.
    if let Some((size, _)) = ancestors.last() {
        segments.push(('█', scaled_round(*size, total, width as u64)));
    }
    for (size, depth) in ancestors[..ancestors.len().saturating_sub(1)]
        .iter()
        .rev()
    {
        segments.push((
            ancestor_char(*depth),
            scaled_round(*size, total, width as u64),
        ));
    }
    let mut bar = String::new();
    let mut previous: u64 = 0;
    for (ch, boundary) in segments {
        let count = boundary.saturating_sub(previous);
        if count > 0 {
            // Do not build far beyond the visible width in pathological cases.
            let already = bar.chars().count();
            let take = (count as usize).min(width.saturating_sub(already));
            for _ in 0..take {
                bar.push(ch);
            }
            if bar.chars().count() >= width {
                break;
            }
        }
        previous = previous.max(boundary);
    }
    while bar.chars().count() < width {
        bar.push(' ');
    }
    if align_right {
        bar.chars().rev().collect()
    } else {
        bar
    }
}

fn tree_size_width<Name: Display>(
    node: &DataTree<Name>,
    unit: Unit,
    bytes_format: &BytesFormat,
) -> usize {
    let own = format_sized(sized_from_unit(node.size, unit), bytes_format).len();
    node.children
        .iter()
        .map(|child| tree_size_width(child, unit, bytes_format))
        .fold(own, Ord::max)
}

fn terminal_width() -> usize {
    for fd in [libc::STDOUT_FILENO, libc::STDERR_FILENO, libc::STDIN_FILENO] {
        let mut winsize: libc::winsize = unsafe { std::mem::zeroed() };
        let result = unsafe { libc::ioctl(fd, libc::TIOCGWINSZ, &mut winsize) };
        if result == 0 && winsize.ws_col > 0 {
            return winsize.ws_col as usize;
        }
    }
    150
}

#[derive(Clone, Copy)]
enum BarMode {
    Fixed(usize),
    Fill,
}

fn total_width_layout(total_width: usize, size_width: usize) -> (usize, BarMode) {
    let other = size_width + 7;
    if total_width <= other {
        (other, BarMode::Fixed(3))
    } else if total_width < 18 {
        (other, BarMode::Fixed(20))
    } else if size_width < 10 {
        (total_width - 17, BarMode::Fill)
    } else {
        let available = total_width - other;
        if available < 7 {
            (available, BarMode::Fill)
        } else {
            (total_width, BarMode::Fill)
        }
    }
}

fn visualize<Name: Display>(
    tree: &DataTree<Name>,
    args: &Args,
    unit: Unit,
) -> String {
    let size_width = tree_size_width(tree, unit, &args.bytes_format);
    let (tree_width_max, bar_mode) = if let Some((tree_width, bar_width)) = args.column_width {
        (tree_width, BarMode::Fixed(bar_width))
    } else {
        let total = args.total_width.unwrap_or_else(terminal_width);
        total_width_layout(total, size_width)
    };

    let Some(visual_root) = build_visual_tree(tree, 0, tree_width_max) else {
        return String::new();
    };

    let orientation = if args.top_down {
        Orientation::TopDown
    } else {
        Orientation::BottomUp
    };
    let mut rows = Vec::new();
    collect_rows(
        &visual_root,
        0,
        true,
        &mut Vec::new(),
        &mut Vec::new(),
        orientation,
        unit,
        &args.bytes_format,
        &mut rows,
    );
    if orientation == Orientation::BottomUp {
        rows.reverse();
    }
    let tree_width_actual = rows
        .iter()
        .map(|row| UnicodeWidthStr::width(row.tree_text.as_str()))
        .max()
        .unwrap_or(0);
    let bar_width = match bar_mode {
        BarMode::Fixed(width) => width.max(1),
        BarMode::Fill => {
            let total = args.total_width.unwrap_or_else(terminal_width) as i128;
            let raw = total - (size_width as i128) - 7 - (tree_width_actual as i128);
            if raw < 1 {
                1
            } else {
                raw as usize
            }
        }
    };

    let mut output_lines = Vec::new();
    for row in &rows {
        let tree_padding = tree_width_actual
            .saturating_sub(UnicodeWidthStr::width(row.tree_text.as_str()));
        let percent = scaled_round(row.size, tree.size, 100);
        let bar = make_bar(&row.ancestors, tree.size, bar_width, args.align_right);
        output_lines.push(format!(
            "{size:>size_width$} {tree}{padding}│{bar}│{percent:>3}%",
            size = row.size_text,
            tree = row.tree_text,
            padding = " ".repeat(tree_padding),
        ));
    }
    output_lines.join("\n")
}

fn print_chart<Name: Display>(
    tree: &DataTree<Name>,
    args: &Args,
    unit: Unit,
    summary: Option<&Summary>,
    from_json_input: bool,
) {
    let chart = visualize(tree, args, unit);
    let mut text = chart;
    if let Some(summary) = summary {
        if !text.is_empty() {
            text.push('\n');
        }
        text.push_str(&render_summary(summary, unit, &args.bytes_format));
    }
    if !text.is_empty() {
        println!("{text}");
        if from_json_input && summary.is_some() {
            println!();
        }
    }
}

// ---------- JSON-input flow ----------

fn run_json_input(args: &Args) -> Result<(), AppError> {
    if !args.files.is_empty() {
        return Err(AppError::JsonInputArgConflict);
    }
    let data: JsonData = serde_json::from_reader(io::stdin().lock())
        .map_err(AppError::DeserializationFailure)?;
    let unit = data.unit;
    let tree = reflection_to_tree(data.tree);
    validate_json_tree(&tree, unit)?;
    let summary = match &data.shared {
        Some(shared) => {
            if let Some(summary) = shared.summary {
                Some(summary)
            } else if let Some(details) = &shared.details {
                Some(summary_of_details(details))
            } else {
                None
            }
        }
        None => None,
    };
    print_chart(&tree, args, unit, summary.as_ref(), true);
    Ok(())
}

// ---------- Filesystem flow ----------

fn run_filesystem(args: &Args) {
    let mut files = args.files.clone();
    if files.is_empty() {
        files.push(PathBuf::from("."));
    }
    if args.deduplicate_hardlinks {
        files = remove_overlapping_dir_args(files);
    }

    let reporter = Reporter::new(args.silent_errors, args.progress);
    let collector = HardlinkCollector::default();
    let builder = TreeBuilder {
        quantity: match args.quantity {
            Quantity::ApparentSize => Quantity::ApparentSize,
            Quantity::BlockSize => Quantity::BlockSize,
            Quantity::BlockCount => Quantity::BlockCount,
        },
        sort: !args.no_sort,
        reporter: Arc::clone(&reporter),
        hardlinks: if args.deduplicate_hardlinks {
            Some(collector.clone())
        } else {
            None
        },
    };

    let build_forest = |builder: &TreeBuilder, files: &[PathBuf]| -> Vec<DataTree<OsStringDisplay>> {
        files
            .par_iter()
            .map(|path| {
                builder.build(
                    path.clone(),
                    OsStringDisplay(path.as_os_str().to_os_string()),
                )
            })
            .collect()
    };

    let forest = match &args.threads {
        Threads::Number(number) => {
            let pool = rayon::ThreadPoolBuilder::new()
                .num_threads(number.get())
                .build()
                .unwrap();
            pool.install(|| build_forest(&builder, &files))
        }
        Threads::Auto | Threads::Max => build_forest(&builder, &files),
    };
    reporter.finish();

    let root_is_total = forest.len() > 1;
    let mut tree = if forest.len() == 1 {
        forest.into_iter().next().expect("single tree")
    } else {
        let total = forest.iter().fold(0u64, |sum, node| sum.wrapping_add(node.size));
        let mut combined = DataTree::new(
            OsStringDisplay(OsString::from("(total)")),
            total,
            forest,
        );
        if !args.no_sort {
            combined
                .children
                .sort_by(|left, right| right.size.cmp(&left.size));
        }
        combined
    };

    prune_tree(&mut tree, &args.max_depth, args.min_ratio);

    let records = if args.deduplicate_hardlinks {
        collector.snapshot()
    } else {
        HardlinkMap::new()
    };
    if args.deduplicate_hardlinks && !records.is_empty() {
        adjust_hardlinked_sizes(&mut tree, &records, root_is_total);
    }

    let unit = unit_of(&args.quantity);

    if args.json_output {
        let reflection = tree_to_reflection(tree);
        let shared = if !records.is_empty()
            && !(args.omit_json_shared_details && args.omit_json_shared_summary)
        {
            let summary = summary_of_map(&records);
            let details = records
                .iter()
                .map(|(ino, record)| ReflectionEntry {
                    ino: *ino,
                    size: record.size,
                    links: record.links,
                    paths: record.paths.clone(),
                })
                .collect::<Vec<_>>();
            Some(JsonShared {
                details: if args.omit_json_shared_details {
                    None
                } else {
                    Some(details)
                },
                summary: if args.omit_json_shared_summary {
                    None
                } else {
                    Some(summary)
                },
            })
        } else {
            None
        };
        let data = JsonData {
            schema_version: SCHEMA_VERSION.to_string(),
            pdu: Some(env!("CARGO_PKG_VERSION").to_string()),
            unit,
            tree: reflection,
            shared,
        };
        let _ = serde_json::to_writer(io::stdout().lock(), &data);
        return;
    }

    let summary = if records.is_empty() {
        None
    } else {
        Some(summary_of_map(&records))
    };
    print_chart(&tree, args, unit, summary.as_ref(), false);
}

fn main() -> ExitCode {
    let args = parse_args();
    if args.json_input {
        match run_json_input(&args) {
            Ok(()) => ExitCode::from(0),
            Err(error) => {
                eprintln!("[error] {error}");
                ExitCode::from(error.code())
            }
        }
    } else {
        run_filesystem(&args);
        ExitCode::from(0)
    }
}
