#[derive(Clone, Debug)]
struct OsStringDisplay(OsString);

impl Display for OsStringDisplay {
    fn fmt(&self, formatter: &mut fmt::Formatter<'_>) -> fmt::Result {
        match self.0.to_str() {
            Some(text) => formatter.write_str(text),
            None => write!(formatter, "{:?}", self.0),
        }
