p='src/main.rs';s=open(p).read()
# Add merge method to collector by inserting before fn snapshot
s=s.replace("""    fn snapshot(&self) -> HardlinkMap {
        self.records.lock().expect("hardlink mutex").clone()
    }
""", """    fn snapshot(&self) -> HardlinkMap {
        self.records.lock().expect("hardlink mutex").clone()
    }

    fn merge(&self, other: HardlinkMap) {
        let mut records = self.records.lock().expect("hardlink mutex");
        for (ino, incoming) in other {
            let record = records.entry(ino).or_insert_with(|| HardlinkRecord {
                size: incoming.size,
                links: incoming.links,
                paths: HashSet::new(),
                path_counts: HashMap::new(),
                detected_links: 0,
            });
            for path in incoming.paths {
                record.paths.insert(path);
            }
            for (path, count) in incoming.path_counts {
                *record.path_counts.entry(path).or_insert(0) += count;
            }
            record.detected_links += incoming.detected_links;
        }
    }
""")
# Replace tree builder setup and build_forest closure
old_start=s.index("    let reporter = Reporter::new")
old_end=s.index("    reporter.finish();",old_start)
replacement='''    let reporter = Reporter::new(args.silent_errors, args.progress);
    let collector = HardlinkCollector::default();

    let build_forest = |files: &[PathBuf]| -> Vec<DataTree<OsStringDisplay>> {
        let built: Vec<(DataTree<OsStringDisplay>, Option<HardlinkCollector>)> = files
            .par_iter()
            .map(|path| {
                let local_collector = if args.deduplicate_hardlinks {
                    Some(HardlinkCollector::default())
                } else {
                    None
                };
                let builder = TreeBuilder {
                    quantity: match args.quantity {
                        Quantity::ApparentSize => Quantity::ApparentSize,
                        Quantity::BlockSize => Quantity::BlockSize,
                        Quantity::BlockCount => Quantity::BlockCount,
                    },
                    sort: !args.no_sort,
                    reporter: Arc::clone(&reporter),
                    hardlinks: local_collector.clone(),
                };
                let tree = builder.build(
                    path.clone(),
                    OsStringDisplay(path.as_os_str().to_os_string()),
                );
                (tree, local_collector)
            })
            .collect();
        let mut forest = Vec::new();
        for (tree, local_collector) in built {
            if let Some(local_collector) = local_collector {
                collector.merge(local_collector.snapshot());
            }
            forest.push(tree);
        }
        forest
    };

    let forest = match &args.threads {
        Threads::Number(number) => {
            let pool = rayon::ThreadPoolBuilder::new()
                .num_threads(number.get())
                .build()
                .unwrap();
            pool.install(|| build_forest(&files))
        }
        Threads::Auto | Threads::Max => build_forest(&files),
    };
'''
s=s[:old_start]+replacement+s[old_end:]
open(p,'w').write(s)
