                kwargs[name]=subprocess.PIPE
            else: kwargs[name]=subprocess.PIPE
        else:
            m,s=pty.openpty();fcntl.ioctl(s,termios.TIOCSWINSZ,struct.pack("HHHH",24,cols,0,0));fds[name]=(m,s);masters.append(m);kwargs[name]=s
    p=subprocess.Popen([exe]+args,**kwargs)
    for m,s in fds.values():os.close(s)
    # if stdin pipe, send input after? for json cases use communicate on pipes only if no ptys complexities- not used
    if "stdin" not in fds and inp is not None:
        try:p.stdin.write(inp);p.stdin.close()
        except BrokenPipeError:pass
