    # Read pty masters until process exits with select
    bufs={name:b"" for name in fds}
    while p.poll() is None:
        if not masters:break
        r,_,_=select.select(masters,[],[],0.05)
        for m in r:
            try:c=os.read(m,65536)
            except OSError:c=b""
            # identify name
            for name,(mm,ss) in fds.items():
                if mm==m:bufs[name]+=c
    for name,(m,s) in fds.items():
