            r,_,_=select.select([m],[],[],0.05)
            if not r:break
            try:c=os.read(m,65536)
            except OSError:break
            if not c:break
            bufs[name]+=c
    # collect pipes
    if "stdout" in fds: out=bufs["stdout"]
    else: out=p.stdout.read() if p.stdout else b""
    if "stderr" in fds: err=bufs["stderr"]
    else: err=p.stderr.read() if p.stderr else b""
    p.wait()
    for m in masters:os.close(m)
    # pty translates \n to \r\n; normalize that only? Keep raw, both same pty translation.
    return p.returncode,out,err

def cmp(args,**kw):
    a=run(REF,args,**kw);b=run(MY,args,**kw)
    print("OK" if a==b else "DIFF",args,kw)
    if a!=b:
        print("ref",a);print("my",b)

