  let cand_f64_wrap = (p64 as f64/total as f64).round() as u64;
  let cand_int = ((p64 as u128+(total/2) as u128)/total as u128) as u64;
  println!("{} {} u32={} i32={} f32w={} f64w={} int={}",size,total,cand_u32,cand_i32,cand_f32_wrap,cand_f64_wrap,cand_int);
